;object-fit:contain;background:#faf8f1}.card-body{padding:12px 15px 15px;display:flex;flex-direction:column;flex:1}.note{font-size:13px;color:var(--muted);margin:0 0 10px}.burden{font-size:13px;line-height:1.65;margin:0 0 10px}.frontier{color:var(--teal);font-weight:650}.inspect{align-self:flex-start;margin-top:auto;font-size:13px;padding:7px 10px}.empty{grid-column:1/-1;padding:35px;border:1px dashed var(--line);text-align:center;color:var(--muted)}.inspection{margin:20px 0 28px;padding:21px;border:2px solid #789994;border-radius:7px;background:var(--white)}.inspection[hidden]{display:none}.inspection-head{display:flex;justify-content:space-between;gap:12px}.inspection-head button{font-size:13px;padding:5px 10px}.comparison{display:grid;grid-template-columns:1fr 1fr;gap:20px;margin:16px 0}.comparison figure{margin:0;min-width:0}.comparison figcaption{font-size:13px;margin:0 0 7px}.comparison img{width:100%;height:245px;object-fit:contain;background:#f8f6ef}.fact{font-weight:650;white-space:nowrap}.tier{white-space:nowrap}.signature{margin-top:32px;border-top:1px solid var(--line);padding-top:23px}.signature ul{padding-left:20px}.signature li{margin-bottom:12px;font-size:14px}.signature code{font-size:12px;color:var(--teal)}.signature .solutions{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.solution{padding:13px 15px;border:1px solid var(--line);border-radius:5px;background:var(--white);font-size:13px}.solution p{margin:5px 0 0;overflow-wrap:anywhere}.solution strong{font-size:14px}.limits{margin-top:30px;padding-top:22px;border-top:1px solid var(--line);font-size:13px}.limits li{margin:9px 0}footer{margin-top:26px;font-size:13px;color:var(--muted)}[hidden]{display:none!important}
